INSERT INTO pec.parametro SELECT k.faz, v.c, v.val::jsonb, v.d FROM k, (VALUES ('DIAS_ATE_DG','30','Dias entre IATF e DG'),('DIV_BAIXA_CAB','2','Divergência baixa até N cab.'),('DIV_BAIXA_PCT','0.02','Divergência baixa até %'),('DIV_MEDIA_PCT','0.05','Divergência média até %'),('ESTOQUE_NEGATIVO','"ALERTAR"','Política de estoque negativo'),('LOTACAO_MAX','1.5','Lotação máxima desejada (UA/ha)'),('LOTACAO_MIN','0.7','Lotação mínima desejada (UA/ha)'),('PN_PADRAO_F','30','Peso ao nascer padrão fêmea (kg) — confirmar'),('PN_PADRAO_M','32','Peso ao nascer padrão macho (kg) — confirmar')) v(c,val,d);
INSERT INTO pec.retiro (fazenda_id, nome, sigla, area_informada_ha, tipo, ordem) SELECT k.faz, v.* FROM k, (VALUES ('Água Funda','AgF',NULL::numeric,'PASTO',1),('Pontal','Pon',NULL::numeric,'PASTO',2),('Seringa','Ser',NULL::numeric,'PASTO',3),('Placa','Pla',NULL::numeric,'PASTO',4),('Queimada','Que',NULL::numeric,'PASTO',5),('Potrillo','Pot',NULL::numeric,'PASTO',6),('Confinamento','Conf',NULL::numeric,'CONFINAMENTO',7),('ILP - Pastoril','ILPPas',NULL::numeric,'ILP',8),('ILP - Potrillo','ILPPot',NULL::numeric,'ILP',9)) v;
INSERT INTO pec.categoria (organizacao_id, nome, sexo, fase, idade_min_meses, idade_max_meses, permite_nascimento, eh_matriz, grupo_dashboard, coluna_mapao, ordem) SELECT k.org, v.n, v.s::pec.sexo_t, v.f::pec.fase_cat_t, v.i1, v.i2, v.pn, v.m, v.g, v.cm, v.o FROM k, (VALUES ('Vaca','F','MATRIZ',NULL::int,NULL::int,False,True,'Matrizes','MATRIZES – VACA (col. C)',1),('Primípara','F','MATRIZ',NULL::int,NULL::int,False,True,'Matrizes','MATRIZES – PRIMÍPARA (col. D)',2),('Novilha Matriz','F','MATRIZ',NULL::int,NULL::int,False,True,'Matrizes','MATRIZES – NOVILHA (col. E)',3),('Leiteira','F','LEITEIRA',NULL::int,NULL::int,False,False,'Matrizes','MATRIZES – LEITEIRA (col. F)',4),('Bez. Macho','M','BEZERRO',0::int,8::int,True,False,'Bezerros ao pé','BEZ. MACHO MAM. (col. G)',5),('Bez. Fêmea','F','BEZERRO',0::int,8::int,True,False,'Bezerros ao pé','BEZ. FÊMEA MAM. (col. H)',6),('Vaca Descarte','F','DESCARTE',NULL::int,NULL::int,False,False,'Descarte','VACA DESCARTE (col. I)',7),('Desmama Fêmea','F','RECRIA',8::int,12::int,False,False,'Recria','FÊMEAS – DESMAME 8 a 12 m (col. J)',8),('Novilha','F','RECRIA',13::int,24::int,False,False,'Recria','FÊMEAS – NOVILHAS 13 a 24 m (col. K)',9),('Fêmea Descarte','F','DESCARTE',NULL::int,NULL::int,False,False,'Descarte','FÊMEAS – DESCARTE (col. L)',10),('Desmama Macho','M','RECRIA',8::int,12::int,False,False,'Recria','MACHOS – DESMAME 8 a 12 m (col. M)',11),('Garrote','M','RECRIA',13::int,24::int,False,False,'Recria','MACHOS – GARROTE 13 a 24 m (col. N)',12),('Boi','M','ENGORDA',25::int,NULL::int,False,False,'Bois','MACHOS – BOI > 24 m (col. O)',13),('Touro','M','REPRODUTOR',NULL::int,NULL::int,False,False,'Touros','TOURO (col. P)',14)) v(n,s,f,i1,i2,pn,m,g,cm,o);
INSERT INTO pec.categoria_parametro (categoria_id, vigente_desde, fator_ua, meta_mortalidade) SELECT c.id, '2000-01-01', v.ua, v.meta FROM pec.categoria c JOIN (VALUES ('Vaca',1.000,0.0150),('Primípara',0.900,0.0200),('Novilha Matriz',0.750,0.0150),('Leiteira',1.000,0.0150),('Bez. Macho',0.250,0.0400),('Bez. Fêmea',0.250,0.0400),('Vaca Descarte',1.000,0.0150),('Desmama Fêmea',0.450,0.0200),('Novilha',0.650,0.0150),('Fêmea Descarte',0.800,0.0150),('Desmama Macho',0.500,0.0200),('Garrote',0.700,0.0150),('Boi',1.100,0.0150),('Touro',1.400,0.0150)) v(n,ua,meta) ON v.n = c.nome;
INSERT INTO pec.categoria_transicao SELECT a.id, b.id, v.op, v.g FROM (VALUES ('Bez. Macho','Desmama Macho','DESMAMA','desmama (8 m)'),('Bez. Fêmea','Desmama Fêmea','DESMAMA','desmama (8 m)'),('Bez. Macho','Desmama Macho','ERA','correção de classificação sem pesagem'),('Bez. Fêmea','Desmama Fêmea','ERA','correção de classificação sem pesagem'),('Desmama Macho','Garrote','ERA','13 meses'),('Garrote','Boi','ERA','25 meses'),('Desmama Fêmea','Novilha','ERA','13 meses'),('Novilha','Novilha Matriz','ERA','entrada em reprodução'),('Novilha Matriz','Primípara','ERA','1º parto'),('Primípara','Vaca','ERA','2º parto'),('Vaca','Primípara','ERA','correção: vaca de 1ª cria'),('Vaca','Vaca Descarte','ERA','descarte'),('Primípara','Vaca Descarte','ERA','descarte'),('Novilha Matriz','Fêmea Descarte','ERA','descarte'),('Novilha','Fêmea Descarte','ERA','descarte'),('Desmama Fêmea','Fêmea Descarte','ERA','descarte'),('Vaca','Leiteira','ERA','separação para leite'),('Leiteira','Vaca','ERA','retorno ao rebanho de cria')) v(de,para,op,g) JOIN pec.categoria a ON a.nome=v.de JOIN pec.categoria b ON b.nome=v.para;
