INSERT INTO pec.documento (fazenda_id, operacao_codigo, data, observacao, origem, importacao_id, linha_origem) SELECT k.faz, op, data, obs, 'IMPORTACAO', (SELECT id FROM pec.importacao), linha FROM k, carga ORDER BY data, linha;
INSERT INTO pec.movimento (documento_id, sentido, fazenda_id, retiro_id, pasto_id, lote_id, categoria_id, raca_id, quantidade, data, status_reprodutivo)
INSERT INTO pec.pendencia (fazenda_id, origem, titulo, descricao, acao_recomendada, retiro_id, prioridade, status) SELECT k.faz, 'IMPORTACAO', v.t, v.d, v.a, r.id, v.p::pec.prioridade_t, v.s::pec.status_pend_t FROM k, (VALUES ('Lote 02 (sem pasto) — Placa','90 vacas paridas sem nenhum bezerro lançado.','Contar os bezerros ao pé e lançar machos e fêmeas (Nascimento).','Placa','ALTA','ABERTA'),('Pon-1 · Lote 01 — Pontal','49 vacas paridas x 34 bezerros: 15 vacas sem cria lançada.','Conferir no curral; lançar bezerros faltantes ou Saída - Morte com causa.','Pontal','ALTA','ABERTA'),('Lote 02 (sem pasto) — Pontal','80 vacas x 79 bezerros: diferença de 1.','Confirmar; se morte, lançar Saída - Morte com causa.','Pontal','MEDIA','ABERTA'),('Lotes sem pasto — Pontal / Placa','Lançamentos sem pasto (aparecem na linha SEM PASTO da frente do Mapão).','Informar o pasto (código do mapa, ex.: Pla-3) na aba Lançamentos.',NULL,'ALTA','ABERTA'),('Conf-Geral — Confinamento','10 Bez. Macho no confinamento.','Se já desmamados, reclassificar: Saída - Transferência de Era (Bez. Macho) + Entrada (Desmama Macho).','Confinamento','BAIXA','ABERTA'),('— — Todos','Vacas de 1ª cria lançadas como Vaca.','Se houver primíparas, reclassificar por Transferência de Era (Vaca → Primípara).',NULL,'MEDIA','ABERTA'),('— — Todos','Bezerros ''Angus'' filhos de vaca Nelore.','Se for IATF com sêmen Angus, trocar raça para ''½ Angus x Nelore (F1)''.',NULL,'BAIXA','ABERTA'),('— — Todos','Nenhuma morte ou venda lançada desde 01/07/26.','Lançar mortes/vendas ocorridas; o vaqueiro anota no campo e o escritório lança.',NULL,'MEDIA','ABERTA'),('— — Confinamento / ILPs','Sem mapa e sem área cadastrada.','Informar a área em Cadastros (coluna D).',NULL,'BAIXA','ABERTA'),('Pot-20, 22, 24, 26 a 29 — Potrillo','Pastos abaixo da linha vermelha do mapa.','Confirmar se são Potrillo ou ILP - Potrillo (mudar na aba Pastos).','Potrillo','BAIXA','ABERTA'),('Pon-6A — Pontal','Área 0 ha no mapa.','Conferir área.','Pontal','BAIXA','ABERTA')) v(t,d,a,rn,p,s) LEFT JOIN pec.retiro r ON r.nome = v.rn;
